const path = require('node:path');
const { DatabaseSync } = require('node:sqlite');

const text = (...parts) => parts.join('\n\n');
const geometryDiagram = (caption) => `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 180" role="img" aria-label="${caption}"><rect width="300" height="180" fill="white"/><path d="M45 140 155 165 255 105 145 80Z M45 140 150 25 255 105 M150 25 145 80" fill="none" stroke="#183153" stroke-width="2"/><path d="M45 140 255 105" stroke="#c64b3b" stroke-width="2" stroke-dasharray="5 4"/><text x="142" y="20" font-size="15">S</text><text x="32" y="155" font-size="15">A</text><text x="155" y="178" font-size="15">B</text><text x="260" y="108" font-size="15">C</text><text x="138" y="78" font-size="15">D</text><text x="12" y="42" font-size="12" fill="#334">${caption}</text></svg>`;

const updates = {
  '002FC3': ['а) да; б) нет; в) 6', text('а) Условие не требует, чтобы красное число не совпадало с зелёным. Запишем зелёными 29 чисел 3, 6, …, 90, кроме 42, а красным — 21. Каждое из 30 чисел кратно 3, зелёные между собой различны, и сумма равна 1395−42+21=1374<1395. Значит, это возможно.', 'б) Пусть красное число ровно одно. Тогда остальные 29 чисел — различные зелёные, то есть различные положительные кратные 3. Их наименьшая возможная сумма равна 3(1+2+…+29)=1305. Добавление положительного красного числа только увеличит сумму, поэтому 1067 получить нельзя.', 'в) Если красных чисел пять, зелёных 25. Наименьшая возможная сумма равна 7(1+…+5)+3(1+…+25)=105+975=1080>1067. Следовательно, красных нужно не менее шести. Шести достаточно: возьмём красными 7,14,21,28,42,49, а зелёными 3,6,…,66,72,75. Сумма красных равна 161, сумма зелёных равна 906, всего 1067. Ответ: 6.')],
  '12AE34': ['а) да; б) нет; в) 153', text('Обозначим один ход через T: T(a;b)=(a+b;a−b). Два последовательных хода дают T(T(a;b))=(2a;2b). Поэтому после 2k ходов из (100;1) получается (100·2ᵏ;2ᵏ), а после 2k+1 ходов — (101·2ᵏ;99·2ᵏ).', 'а) Последовательно получаем (100;1)→(101;99)→(200;2)→(202;198)→(400;4). Следовательно, пара с большим числом 400 достижима.', 'б) В формулах для чётного и нечётного числа ходов первая координата равна соответственно 100·2ᵏ или 101·2ᵏ. Она не может быть равна 306, поэтому пара (306;288) из (100;1) не получается.', 'в) Для обратного хода из (u;v) находим a=⟦u+v¦2⟧, b=⟦u−v¦2⟧. У пары (306;288) предшественник (297;9), у него предшественник (153;144). Следующий обратный ход потребовал бы полуцелых координат, так как 153+144 нечётно. Значит, возможных начальных пар больше нет; из (153;144) за два хода получается (306;288). Наименьшая первая координата равна 153.')],
  '2907EB': ['а) да; б) нет; в) 139', text('Кратные 20 идут через 20, а кратные 23 — через 23. В искомом отрезке кратных 23 должно быть больше, хотя они встречаются реже.', 'а) На отрезке от 23 до 92 находятся кратные 23: 23,46,69,92 — четыре числа. Кратные 20 здесь: 40,60,80 — три числа. Значит, такой отрезок существует.', 'б) Если на отрезке 11 кратных 23, расстояние между первым и последним не меньше 10·23=230. Такой отрезок содержит не менее 11 кратных 20: промежуток между первым и одиннадцатым кратными 20 равен только 200. Поэтому при десяти кратных 20 нельзя получить одиннадцать кратных 23.', 'в) На отрезке 161,…,299 шесть кратных 20: 180,200,220,240,260,280, и семь кратных 23: 161,184,207,230,253,276,299. В нём 139 чисел. Для восьми кратных 23 нужен разброс не менее 7·23=161, а на любом отрезке с таким разбросом имеется не менее восьми кратных 20. Следовательно, при большей длине преимущество кратных 23 невозможно. Ответ: 139.')],
  '2A4168': ['а) да; б) нет; в) 33', text('Расположим числа по возрастанию: x₁<x₂<… . Достаточно проверять произведение двух наименьших и двух наибольших чисел: все остальные произведения лежат между ними.', 'а) Набор 6,8,9,10,11 подходит, потому что 6·8=48>45, а 10·11=110<120.', 'б) Предположим, что чисел шесть. Если x₁≤6, то из x₁x₂>45 следует x₂≥8, а потому x₅x₆≥11·12=132>120. Если x₁≥7, то x₂≥9, следовательно, x₅x₆≥12·13=156>120. В обоих случаях противоречие.', 'в) Набор 6,8,9,10 имеет сумму 33 и удовлетворяет условиям: 6·8=48>45, 9·10=90<120. Докажем, что меньше нельзя. При x₁≤5 имеем x₂≥10, x₃≥11, x₄≥12, поэтому сумма не меньше 1+10+11+12=34. При x₁≥6 минимально возможны x₁=6, x₂=8, x₃=9, x₄=10, и сумма равна 33. Ответ: 33.')],
  '2DC181': ['а) да; б) да; в) 3', text('Пусть после операции получена пара (x;y). Тогда x=3p+q, y=3q−p. Решая эту систему, получаем p=⟦3x−y¦10⟧, q=⟦x+3y¦10⟧. Поэтому пара (x;y) получается тогда и только тогда, когда x+3y делится на 10: тогда и 3x−y=3(x+3y)−10y тоже делится на 10.', 'а) Для (5;5) имеем 5+3·5=20, поэтому она получается. Действительно, её предшественник равен (1;2), и (3·1+2;3·2−1)=(5;5).', 'б) Если (c;d) получается, то c+3d делится на 10. Для пары (−d;c) нужное число равно −d+3c=3(c+3d)−10d, оно тоже делится на 10. Следовательно, и эта пара получается.', 'в) Для (9;2) число x+3y равно 15, то есть имеет остаток 5 по модулю 10. Чтобы попасть в класс остатка 0, нужно изменить x+3y на −5, 5 или число, отличающееся от них на 10. При расстоянии меньше 3 это невозможно: изменения одной координаты дают вклад ±1 или ±3, двух — сумму таких вкладов. Пара (7;1) подходит, так как 7+3·1=10, и расстояние до (9;2) равно |7−9|+|1−2|=3. Ответ: 3.')],
  '30D64C': ['а) да; б) нет; в) ⟦283¦190⟧', text('Пусть исходное трёхзначное число равно 100a+10b+c, где a∈{1,…,9}, b,c∈{0,…,9}. После прибавления 10b и 3 получается число 100a+20b+c+3.', 'а) Для числа 211 имеем a=2, b=1, c=1. Результат равен 211+10+3=224, поэтому это возможно.', 'б) Если результат равен 314, то 100a+20b+c=311. По последней цифре c=1, откуда 100a+20b=310. Левая часть делится на 20, а правая — нет. Противоречие, следовательно, 314 получить нельзя.', 'в) Искомое отношение равно 1+⟦10b+3¦100a+10b+c⟧. При фиксированном b дробь наибольшая при наименьших a=1 и c=0. Тогда она равна ⟦10b+3¦100+10b⟧. При увеличении b на 1 её числитель растёт на 10, а прямое сравнение соседних дробей показывает рост: разность после приведения к общему знаменателю имеет числитель 970>0. Поэтому b=9. Исходное число 190, результат 283, отношение равно ⟦283¦190⟧.')],
  '354582': ['а) нет; б) нет; в) 21', text('Возьмём два числа из набора и заменим одно другим в любой тройке, четвёрке, пятёрке или шестёрке, остальные числа оставив теми же. Обе суммы целые, значит, разность заменяемых чисел делится соответственно на 3,4,5 и 6. Поэтому все десять чисел имеют одинаковый остаток по НОК(3;4;5;6)=60. Так как 30021≡21 по модулю 60, каждое число имеет вид 60k+21.', 'а) 351≡51 по модулю 60, а не 21. Значит, числа 30021 и 351 не могут стоять на доске одновременно.', 'б) Пусть y=11x — два числа на доске. Тогда y−x=10x делится на 60, то есть x делится на 6. Но число с остатком 21 по модулю 60 не делится на 6. Противоречие.', 'в) Если y=nx, то (n−1)x делится на 60. Для x≡21 по модулю 60 НОД(x;60)=3, следовательно, 20 делит n−1. Наименьшее n>1 равно 21. Оно достигается для x=21, y=441; остальные восемь чисел можно выбрать различными и сравнимыми с 21 по модулю 60. Ответ: 21.')],
  '37B190': ['а) да; б) нет; в) 1430', text('Пусть в первый день Маша сделала m фотографий, Наташа — n, а съёмка длилась t дней. Ежедневная разность не меняется и равна n−m, поэтому разность общих чисел фотографий равна t(n−m)=1001.', 'а) Так как 1001=7·143, при t=7 можно взять n−m=143. Например, m=1, n=144; все условия выполнены.', 'б) Для t=8 число n−m должно было бы равняться ⟦1001¦8⟧, но это не целое число. Значит, восемь дней невозможны.', 'в) Последний дневной результат Маши равен m+t−1 и меньше 40, следовательно, m≤40−t. Кроме того, t — делитель 1001 и t≤39. Возможны t=7,11,13. Для каждого t максимум достигается при m=40−t. Получаем таблицу: при t=7, m=33, n=176, сумма Наташи 7·176+21=1253; при t=11, m=29, n=120, сумма 11·120+55=1375; при t=13, m=27, n=104, сумма 13·104+78=1430. Максимум равен 1430.')],
  '394D51': ['а) нет; б) нет; в) 6', text('Заменим в тройке одно число другим, оставив два остальных. Разность двух получившихся сумм делится на 3, поэтому все числа сравнимы по модулю 3. Тот же приём для пятёрок даёт сравнимость по модулю 5. Следовательно, все числа имеют один и тот же остаток по модулю 15.', 'а) 305≡5 по модулю 15, а 1511≡11 по модулю 15. Поэтому эти два числа вместе записать нельзя.', 'б) Если на доске есть 305, все числа имеют остаток 5 по модулю 15. Квадрат любого числа с таким остатком имеет остаток 5²≡10, а не 5. Значит, одно из чисел не может быть квадратом другого.', 'в) Если на доске есть n и n², необходимо n²≡n по модулю 15. Для n=2,3,4,5 это неверно: остатки n²−n равны 2,6,12,20 и не делятся на 15. При n=6 имеем 36≡6 по модулю 15. Числа 6,36 и ещё восемь различных чисел с остатком 6 по модулю 15 дают требуемый набор. Ответ: 6.')],
  '40BED3': ['а) 6; б) 89; в) 19', text('а) Пусть в школе № 1 первоначально было n учеников, а переведённый ученик набрал x баллов. До перехода сумма равна 18n, после перехода средний балл равен 19,8: ⟦18n−x¦n−1⟧=19,8. Отсюда x=19,8−1,8n. Число x натурально, поэтому 10x=198−18n делится на 10; значит, n≡1 по модулю 5. Из x>0 следует n<11, а n≥2. Получаем n=6 и x=9.', 'б) Сумма баллов шести учеников равна 18·6=108. Среди оставшихся пяти учеников один может иметь наибольший балл, а четыре других должны набрать различные натуральные числа, отличные от 9. Их наименьшая сумма равна 1+2+3+4=10. Поэтому наибольший балл равен 108−9−10=89. Такой набор 1,2,3,4,9,89 существует.', 'в) Пусть во второй школе первоначально m>10 учеников со средним A. После прихода ученика с 9 баллами средний вырос на 10%: ⟦mA+9¦m+1⟧=1,1A. После упрощения A(m+11)=90. Число m+11 — делитель 90 и больше 21; наименьший такой делитель равен 30. Следовательно, m=19, A=3. Ответ: а) 6; б) 89; в) 19.')],
  '4A9559': ['а) да; б) нет; в) да', text('а) Рассмотрим A=779 и B=899. Произведения соответствующих цифр равны 7·8=56, 7·9=63 и 9·9=81. Их сумма 56+63+81=200, поэтому такие трёхзначные числа существуют.', 'б) Каждое произведение двух цифр не превосходит 9·9=81, значит, сумма четырёх произведений не больше 324. Чтобы получить 320, сумма дефицитов 81−aᵢbᵢ должна была бы равняться 4. Однако ненулевой дефицит не меньше 9: ближайшее к 81 меньшее произведение цифр равно 9·8=72. Поэтому дефицит 4 невозможен.', 'в) Одно произведение цифр может принимать, в частности, все значения от 0 до 10, а также 12,14,…,81. Последовательно подбирая пять таких слагаемых, получаем все целые суммы от 1 до 340; первое слагаемое делаем ненулевым, чтобы первая цифра обоих пятизначных чисел не была нулём. Например, выбранные пять произведений реализуются попарно цифрами, дающими эти произведения. Следовательно, утверждение верно.')],
  '5066E8': ['а) да; б) нет; в) 72', text('а) Возьмём круговую расстановку 1,2,3,4,5,6,8,10,7,11,9,12. Модули соседних разностей равны 1,1,1,1,1,2,2,3,4,2,3,11; их сумма равна 32.', 'б) Обойдём круг в выбранном направлении и обозначим разности соседних чисел со знаками через d₁,…,d₁₂. Их сумма равна нулю. Поэтому сумма положительных dᵢ равна по модулю сумме отрицательных, а сумма |dᵢ| вдвое больше суммы положительных. Она всегда чётна, следовательно, 29 получить нельзя.', 'в) Сумма положительных скачков не больше суммы шести наибольших чисел минус суммы шести наименьших: (7+…+12)−(1+…+6)=36. Значит, общая сумма модулей не больше 72. Расстановка 1,7,2,8,3,9,4,10,5,11,6,12 чередует малые и большие числа; все положительные скачки в ней в сумме дают 36. Верхняя граница достигается. Ответ: 72.')],
  '6948DB': ['а) нет; б) 388; в) 187', text('Первый вид хода меняет пару на (a+2;b−1), второй — на (a−1;b+2). В обоих случаях сумма координат увеличивается на 1. Поэтому после N ходов она равна 5+7+N=12+N.', 'а) После 50 ходов сумма равна 62. Если бы одна координата была равна 100, другая была бы отрицательной, что запрещено. Значит, это невозможно.', 'б) Для суммы 400 необходимо N=400−12=388. Сделаем по 194 хода каждого вида. Тогда первая координата равна 5+2·194−194=199, вторая 7−194+2·194=201; обе положительны. Ответ: 388.', 'в) При обеих координатах не больше 100 их сумма не больше 200, значит, N≤188. При N=188 сумма была бы 200 и конечная пара обязана быть (100;100). Если r — число ходов первого вида, то 5+2r−(188−r)=100, то есть 3r=283, что невозможно в целых числах. При N=187 возьмём 94 хода первого вида и 93 второго: получаем (100;99). Ответ: 187.')],
  '6E32AD': ['а) да; б) нет; в) 9', text('Все допустимые числа оканчиваются на 4 или на 9, поэтому каждое сравнимо с 4 по модулю 5.', 'а) Равенство 107=4+9+94 показывает, что нужная сумма возможна.', 'б) Если в сумме k слагаемых, то она сравнима с 4k по модулю 5. Из 289≡4 получаем k≡1 по модулю 5. Одного слагаемого быть не может, так как 289 содержит запрещённые цифры. Следующий вариант — шесть слагаемых, но шесть наименьших различных допустимых чисел имеют сумму 4+9+44+49+94+99=299>289. При большем числе слагаемых сумма тем более больше.', 'в) Из 3986≡1 по модулю 5 следует 4k≡1, то есть k≡4 по модулю 5. Четыре наибольших допустимых числа, не превосходящие 3986, — 999,994,949,944; их сумма 3886<3986. Поэтому k не равно 4, а следующее возможное значение равно 9. Оно достигается: 3986=9+49+99+444+449+494+499+949+994. Ответ: 9.')],
  '724631': ['а) да; б) нет; в) 910', text('Пусть цифры трёхзначного числа A равны a,b,c. После вычёркивания одной цифры могут получиться числа 10a+b, 10a+c и 10b+c. Для каждого из трёх вариантов пары B,C проверяем равенство A=B·C; это даёт конечный перебор цифр a,b,c.', 'Получаем все трёхзначные решения: 100,110,120,121,130,140,150,160,170,180,190,210,310,410,510,610,625,710,810,910. Например, для 910 после вычёркивания средней и последней цифр получаем 10 и 91, а 10·91=910.', 'а) В списке есть 160=10·16, поэтому ответ «да». б) Среди чисел от 540 до 599 ни одного элемента списка нет, значит, ответ «нет». в) Наибольший элемент списка — 910; он действительно реализован разложением 910=10·91. Ответ: 910.')],
  '742D28': ['а) да; б) нет; в) 23', text('Пять последовательных кратных 20 имеют разброс 4·20=80. Чтобы на отрезке было ровно пять таких чисел, его длина не меньше 81 и не больше 119: при длине 120 уже неизбежно встретится шестое кратное 20.', 'а) На отрезке 294,…,399 кратные 20 равны 300,320,340,360,380 — их пять. Кратные 21 равны 294,315,336,357,378,399 — их шесть. Значит, это возможно.', 'б) В любых 81 последовательном числе есть по меньшей мере пять кратных 15, так как пять таких кратных имеют разброс только 60. Наш отрезок содержит не меньше 81 числа, поэтому меньше пяти кратных 15 быть не может.', 'в) Шесть кратных k имеют разброс не меньше 5k. Длина отрезка не больше 119, следовательно, 5k≤118 и k≤23. Для k=23 берём отрезок 21,…,138. В нём пять кратных 20: 40,60,80,100,120, и шесть кратных 23: 23,46,69,92,115,138. Ответ: 23.')],
  '7B10F3': ['а) нет; б) нет; в) 11', text('Пусть k из 30 чисел оканчиваются на 6. Остальные 30−k оканчиваются на 2. Последняя цифра их суммы равна 6k+2(30−k)=60+4k. Так как 2454 оканчивается на 4, получаем 4k≡4 по модулю 10, то есть k≡1 по модулю 5.', 'а) При равном количестве чисел каждого вида было бы k=15, но 15 не сравнимо с 1 по модулю 5. Значит, это невозможно.', 'б) Если k=1, то остальных 29 чисел, оканчивающихся на 2, нужно взять различными. Их минимальная сумма равна 2+12+…+282=4118>2454. Поэтому одного числа с последней цифрой 6 быть не может.', 'в) Возможные k равны 1,6,11,… . При k=6 минимальная сумма шести чисел с концом 6 и 24 чисел с концом 2 уже больше 2454. При k=11 возьмём 6,16,…,106 и 2,12,…,172,272. В первом наборе 11 чисел с суммой 616, во втором 19 чисел с суммой 1838; всего 2454. Ответ: 11.')],
  '7C3FDA': ['а) нет; б) нет; в) 10,5', text('Пусть x₁<x₂<…<x₁₀ — записанные числа. Сумма шести меньших равна 30, сумма шести больших равна 90. При сложении этих двух сумм x₅ и x₆ учтены дважды, поэтому сумма всех десяти чисел равна 120−(x₅+x₆).', 'а) Если x₁=3, то шесть меньших различных чисел не меньше 3,4,5,6,7,8 и имеют сумму не меньше 33, а не 30. Ответ «нет».', 'б) Среднее всех чисел 11 означало бы общую сумму 110, то есть x₅+x₆=10. Но x₅≥5 и x₆≥6, поэтому x₅+x₆≥11. Это невозможно.', 'в) Докажем, что x₅+x₆≥15. Иначе x₅+x₆≤14, а из x₁+x₂+x₃+x₄=30−(x₅+x₆) получили бы сумму первых четырёх не меньше 16. Тогда x₄≥6, ибо при x₄≤5 их сумма не превосходит 2+3+4+5=14. Но при x₄≥6 имеем x₅≥7 и x₆≥8, то есть x₅+x₆≥15 — противоречие. Поэтому общая сумма не больше 120−15=105, а среднее не больше 10,5. Набор 2,3,4,6,7,8,14,16,22,23 имеет суммы 30 и 90 для требуемых шестёрок и среднее 10,5. Ответ: 10,5.')],
  '7CA5F3': ['а) да; б) нет; в) 198', text('Сумма камней сохраняется и остатки разностей чисел в коробках по модулю 3 не меняются.', 'а) Последовательность из пяти ходов с переносом в третью коробку, пяти ходов с переносом в первую и ещё пяти ходов с переносом в третью приводит к (97;89;15).', 'б) Для (0;0;201) разность первой и третьей коробок имеет другой остаток по модулю 3.', 'в) При одном камне в первой коробке третья должна быть кратна 3, поэтому максимум не больше 198. Он достигается: 97 раз переносим в третью, 2 раза — в первую, 3 раза — в третью; получаем (1;2;198).')],
  '8381FC': ['а) да; б) нет; в) 303', text('Сумма камней сохраняется, а разности чисел в коробках по модулю 4 не меняются.', 'а) Два раза переносим три камня в четвёртую коробку, затем по разу — во вторую и третью: получаем (97;102;103;4).', 'б) У набора (0;0;0;306) нарушаются инварианты разностей по модулю 4.', 'в) Пусть в первой коробке X. Тогда числа во второй, третьей и четвёртой сравнимы с X−3, X−2, X−1 по модулю 4. Их минимальная сумма даёт X≤303. Набор (303;0;1;2) достигается: 26 раз переносим в четвёртую, затем 76 раз — в первую.')],
  '8755EE': ['а) да; б) нет; в) 8', text('За один ход число кусков может увеличиться не более чем вдвое.', 'а) Последовательные деления пополам дают 1,2,4,8,16 кусков за четыре хода. б) За пять ходов не больше 32 кусков, поэтому 100 невозможно.', 'в) За семь ходов не больше 128 кусков, значит, нужно не меньше восьми. За первые три хода делим 200 на восемь кусков по 25. Каждый кусок 25 за следующие пять ходов делим по схеме 25→12+13→6+6+6+7→3+3+3+3+3+3+3+4→семь единиц и девять двоек→25 единиц. Ответ: 8.')],
  '920C72': ['а) да; б) нет; в) 2004', text('Пусть первое число 10q+d, где d=1,…,6. Тогда S=4+10q(⟦1¦d⟧+⟦1¦d+1⟧+⟦1¦d+2⟧+⟦1¦d+3⟧).', 'а) При d=2, q=1 получаем числа 12,13,14,15 и S=16⟦5¦6⟧. б) Подстановка d=1,…,6 в формулу не даёт целого q для 569⟦29¦126⟧.', 'в) При d=1 имеем S=4+⟦125q¦6⟧. Для целого S q кратно 6, наибольшее q≤99 равно 96, что даёт 2004. При d≥2 сумма меньше 1275. Ответ: 2004.')],
  '9BC08F': ['а) да; б) нет; в) 51', text('Пусть исходное число равно 100a+10b+c. Из него вычитают сумму цифр a+b+c и делят результат на 3. Поэтому полученное число равно ⟦99a+9b¦3⟧=33a+3b; от цифры c оно не зависит.', 'а) При a=9, b=1 получается 33·9+3=300. Например, исходное число 910 даёт требуемый результат.', 'б) Число 33a+3b всегда делится на 3, а 151 на 3 не делится. Поэтому 151 получить нельзя.', 'в) Для a=1,…,5 и b=0,…,9 получаем пять непересекающихся десятков значений 33a,33a+3,…,33a+27. Это 50 различных результатов для исходных чисел от 100 до 599. Остаётся число 600: оно даёт 33·6=198, а 198 не встречалось при a≤5, потому что последний результат при a=5 равен 192. Всего 51 значение.')],
  '9C9614': ['а) нет; б) нет; в) 4', text('Наименьшая сумма 100 различных натуральных чисел равна 1+2+…+100=5050. Во всех пунктах будем сравнивать данную сумму с наименьшей возможной при дополнительных условиях.', 'а) Если среди чисел есть 230, то вместе с ним для минимальной суммы надо взять 1,2,…,99. Получаем 1+…+99+230=5180>5120. Значит, числа 230 быть не может.', 'б) Без 14 наименьшие 100 натуральных чисел — это 1,2,…,101 без 14. Их сумма равна 1+…+101−14=5137>5120. Следовательно, 14 обязательно присутствует.', 'в) При не более трёх кратных 14 минимальная сумма достигается, когда берём 14,28,42 и 97 наименьших некратных 14 чисел; она равна 5152>5120. Поэтому кратных 14 нужно не менее четырёх. Четыре достаточно: возьмём 14,28,42,56 и 96 наименьших некратных 14 чисел, заменив в этом наборе 103 на 119. Сумма уменьшается до 5120. Ответ: 4.')],
  'A0A7EB': ['а) да; б) да; в) 34', text('а) За семь дней можно записать соответственно: 20 единиц; 18 единиц и 3; 16 единиц и две тройки; …; 8 единиц и шесть троек. Количество чисел ежедневно уменьшается на 1, а суммы 20,21,…,26 возрастают. Значит, n может быть больше 6.', 'б) В первый день запишем 199 двоек и 1: всего 200 чисел с суммой 399, поэтому среднее меньше 2. В следующие дни запишем: 195 пятёрок, 3,3,1,1; затем 195 пятёрок, 5,3,1; затем 195 пятёрок, 5,5. Количества равны 199,198,197, а суммы — 983,984,985. Общее среднее равно ⟦3351¦794⟧>4, поэтому такой пример существует.', 'в) Пусть rᵢ — количество чисел в i-й день, sᵢ — их сумма. Из s₁=5 получаем r₁≤5. Для фиксированной строго убывающей последовательности rᵢ суммы должны удовлетворять 5=s₁<s₂<…<sₙ и sᵢ≤5rᵢ. Перебор возможных rᵢ при r₁≤5 даёт наибольшие общие суммы: 5 при r₁≤2; 15 при (3;2); 24 при (4;3;2); 34 при (5;4;3). Последнее значение достигается наборами 1,1,1,1,1; 3,3,4,4; 5,5,5. Ответ: а) да; б) да; в) 34.')],
  'A68DFB': ['а) нет; б) нет; в) 9', text('Заменяя одно число другим в четвёрке, получаем, что разность любых двух чисел делится на 4. Тот же приём для пятёрок даёт делимость на 5. Следовательно, все числа имеют один остаток по модулю 20. Так как 403≡3 по модулю 20, остаток каждого числа равен 3.', 'а) 2013≡13 по модулю 20, поэтому числа 403 и 2013 не могут быть в одном наборе.', 'б) Квадрат по модулю 20 не может иметь остаток 3: по модулю 4 квадрат равен 0 или 1, а число с остатком 3 по модулю 20 имеет остаток 3 по модулю 4. Значит, квадрат натурального числа не может быть одним из чисел набора при наличии 403.', 'в) При наличии 1 и n² необходимо n²≡1 по модулю 20. Для n=2,…,8 остатки квадратов равны 4,9,16,5,16,9,4; единицы нет. При n=9 имеем 9²=81≡1. Набор 1,21,41,61,81,101,121,141,161,181 подходит. Ответ: 9.')],
  'A8EFB6': ['а) да; б) нет; в) 4', text('Пусть k чисел оканчиваются на 7. Все остальные записанные числа чётные. Общая сумма 810 чётна, а каждое число с последней цифрой 7 нечётно, поэтому k должно быть чётным.', 'а) Возьмём 24 наименьших чётных числа 2,4,…,48 и шесть наименьших чисел с концом 7: 7,17,…,57. Их сумма равна 792. Заменим чётное число 48 на 66; сумма увеличится на 18 и станет равной 810. Значит, 24 чётных числа возможны.', 'б) При двух числах с последней цифрой 7 остальные 28 чисел чётные. Уже их наименьшая сумма 2+4+…+56=812, а вместе с 7 и 17 получаем 836>810. Поэтому двух таких чисел быть не может.', 'в) При k=0 наименьшая сумма 30 чётных чисел равна 930, при k=2 она не меньше 836. Следующее допустимое значение k=4. Берём 26 чётных чисел 2,4,…,50,72 и числа 7,17,27,37; их сумма равна 650+72+88=810. Ответ: 4.')],
  'AB0F0C': ['а) да; б) нет; в) 37', text('Расположим числа по возрастанию. Как и в других задачах такого типа, достаточно контролировать произведения двух наименьших и двух наибольших чисел.', 'а) Набор 7,9,10,11,12 подходит: 7·9=63>60, а 11·12=132<140.', 'б) Предположим, что чисел шесть. Если первое не больше 6, то второе не меньше 11; тогда два последних не меньше 14 и 15, их произведение больше 140. Если первое не меньше 7, то второе не меньше 9, а два последних не меньше 12 и 13; их произведение 156>140. В обоих случаях получено противоречие.', 'в) Набор 7,9,10,11 имеет сумму 37 и удовлетворяет 7·9>60, 10·11<140. Если первое число не больше 6, минимальный случай начинается с 6,11,12,13 и даёт сумму 42. Если первое не меньше 8, сумма четырёх различных чисел не меньше 8+9+10+11=38. Значит, 37 — наименьшая возможная сумма.')],
  'AB3CF8': ['а) нет; б) нет; в) 184', text('Из сравнения двух соседних сумм из четырёх чисел получаем периодичность остатков по модулю 4 с периодом 4. Условие для трёх чисел даёт либо четыре нечётных остатка, либо схему нечётный, чётный, чётный, нечётный.', 'На отрезке 1…365 содержатся 92 числа с остатком 1 и по 91 числу остальных остатков. Поэтому в одном периоде можно повторить не более 46 раз схему 1,0,2,1: получаем 184 числа. Схема достижима, а 200 требует больше чисел одного остатка. При N=109 период сворачивается в один остаток, что невозможно. Ответ: 184.')],
  'AED2BB': ['а) нет; б) нет; в) ⟦24¦11⟧', text('Пусть x₁<x₂<…<x₁₁, а B=x₆. Суммы шести меньших и шести больших чисел равны 30 и 90. В этих суммах B учтено дважды, поэтому сумма всех чисел равна 120−B.', 'а) Если x₁=3, шесть меньших различных чисел не меньше 3,4,5,6,7,8 и имеют сумму не меньше 33. Это противоречит сумме 30.', 'б) Среднее всех 11 чисел, равное 9, означало бы общую сумму 99 и B=120−99=21. Но тогда уже первые шесть чисел имеют сумму не меньше 1+2+3+4+5+21=36>30. Это невозможно.', 'в) Выражение S−B равно ⟦120−B¦11⟧−B=⟦120−12B¦11⟧, поэтому надо минимизировать B. При B≤7 сумма пяти различных натуральных чисел, меньших B, не превосходит 2+3+4+5+6=20; вместе с B получается меньше 30. Значит, B≥8. Равенство достигается набором 1,3,5,6,7,8,9,10,11,12,40. Тогда S−B=⟦112¦11⟧−8=⟦24¦11⟧.')],
  'B5D110': ['а) да; б) нет; в) 10', text('Пусть суммы групп A,B,C, а числа элементов a,b,c. После приписывания цифр новая сумма равна 10A+10B+C+a+8b.', 'а) Для групп {1},{2},{9} получаем 48=4·12. б) Увеличение в 18 раз невозможно: добавление цифры к любому натуральному числу даёт меньше 18 его величин.', 'в) Условие увеличения в 11 раз: A+B+10C=a+8b. Для p,q,r чисел минимальная левая часть при заданных p,q,r получается на наименьших различимых числах; отсюда p+q+r≤10. Равенство даёт {2}, {3,4,5,6,7,8,9,11}, {1}: A+B+10C=65=a+8b.')],
  'C690EB': ['а) нет; б) да; в) 48', text('Как и в задаче A0A7EB, дней не больше пяти.', 'б) Количества 40,39,38,37,36 и суммы 119,177,178,179,180 дают среднее первого дня меньше 3, а общее — больше 4.', 'в) При первой сумме 6 число чисел в первый день не больше 6. Максимум дают количества 6,5,4,3 и суммы 6,13,14,15. Общая сумма 48.')],
  'C794EA': ['а) да; б) нет; в) 231', text('а) 2043=9+2034, и суммы цифр обоих слагаемых равны 9.', 'б) При вычитании x из 599 не возникает заём, поэтому суммы цифр x и 599−x в сумме дают 23. Равными они быть не могут.', 'в) Для суммы цифр 6 семь наименьших чисел: 6,15,24,33,42,51,60; их сумма 231. При суммах цифр 1,…,5 седьмое число уже трёхзначное и сумма больше 231; при сумме цифр не меньше 7 первые семь ещё больше. Ответ: 231.')],
  'CFEFEF': ['а) да; б) нет; в) 10035', text('Оба числа кратны 45, поэтому оканчиваются на 0 или 5 и имеют суммы цифр 9 и 18. Возможные трёхзначные части: 135,270,315,720.', 'а) 1935+270=2205. б) Для четырёх возможных трёхзначных частей дополнение до 3435 не составлено из оставшихся цифр, поэтому нет.', 'в) Наибольшие суммы в четырёх случаях: 9855, 9585, 10035, 10035. Например, 9720+315=10035. Ответ: 10035.')],
  'D51CAD': ['а) нет; б) нет; в) 266', text('Сравнение соседних сумм из четырёх чисел даёт период остатков по модулю 3 с периодом 4. Так как сумма каждой тройки не делится на 3, в периоде должны быть две единицы и две двойки.', 'Для N, кратного 4, получаем не более 2·133+2·133=266 чисел. При N≡2 по модулю 4 можно чередовать остатки 1 и 2; ровно 266 чисел с этими остатками существуют. N=360 требует по 180 чисел каждого остатка, а N=149 сводит период к одному остатку и нарушает условие. Ответ: 266.')],
  'D5588E': ['а) нет; б) нет; в) 8,9', text('Пусть числа упорядочены. Суммы шести меньших и шести больших равны 36 и 72, поэтому общая сумма равна 108−(x₅+x₆).', 'а) Шесть различных чисел не больше 14 имеют сумму не больше 69. б) Среднее 8,4 требовало бы x₅+x₆=24, но последние четыре тогда уже дают слишком большую сумму.', 'в) Из первых шести x₅+x₆≤26, а из последних шести x₅+5x₆≤62. Максимум x₅+x₆=19 при 9 и 10. Набор 1,2,6,8,9,10,11,12,13,17 достигает среднего 8,9.')],
  'D6152F': ['а) 4; б) 102; в) 96', text('Пусть во второй школе было m учеников. Из (42m+x):(m+1)=37,8 получаем x=37,8−4,2m. Натуральность даёт m=4, x=21.', 'б) Сумма баллов равна 168. При трёх баллах не меньше 22 максимум четвёртого равен 168−66=102.', 'в) Если в первой школе средний балл A и число учеников n, то (nA−21):(n−1)=0,9A, откуда A(n+9)=210. Наибольшее n получается при A=2: n=96. Такая ситуация реализуема.')],
  'E5791E': ['а) 15; б) нет; в) 80', text('Для удачной тройки a<b<c достаточно и необходимо a≥⟦b+c¦3⟧+5.', 'а) При 50,60,c получаем c≤75, поэтому c=61,…,75: всего 15.', 'б) Для трёх различных чисел a,a+1,a+2 условие даёт a≥18, поэтому число 15 не встречается.', 'в) Если наименьшее число 20, оно может соседствовать лишь с 21,…,24 и круг содержит не более пяти чисел. При наименьшем не меньше 21 чисел не больше 80. Равенство достигается кругом 100,98,…,22,21,23,25,…,99; в каждой тройке разброс не больше четырёх. Ответ: 80.')],
  'E983D6': ['а) да; б) нет; в) 5', text('Пусть в первой школе n учеников, во второй m=9−n.', 'а) При среднем A=10 и переводимом балле 9n+1 оставшиеся n−1 учеников могут иметь по 1 баллу, поэтому десятикратное уменьшение возможно.', 'б) При уменьшении на 10% переводимый балл равен Bn:10. При B=7 и n=2,…,7 это не натуральное число.', 'в) Для каждого n=2,…,7 целочисленность даёт минимальные B: 55,20,65,14,5,80. Минимум 5 достигается при n=6, A=2, переводимом балле 3. Ответ: 5.')],
  'EA76EF': ['а) да; б) нет; в) 31', text('а) Подходит 5,6,7,8,9.', 'б) Для шести чисел последние два неизбежно имеют произведение не меньше 9·10=90, что противоречит строгому ограничению меньше 85.', 'в) Набор 6,7,8,10 имеет сумму 31 и допустим. При третьем числе 8 четвёртое не больше 10, при третьем числе 7 сумма ещё меньше. Значит, 31 — максимум.')],
  'EC9829': ['а) да; б) нет; в) 35', text('а) Подходит 6,7,8,9,10.', 'б) Для шести чисел при первом не больше 6 последние два дают произведение не меньше 11·12, а при первом не меньше 7 второе не меньше 8 и последние числа не меньше 11 и 12. В обоих случаях произведение не меньше 100.', 'в) Набор 7,8,9,11 имеет сумму 35. При третьем числе 9 четвёртое не больше 11, а при меньшем третьем числе сумма меньше. Ответ: 35.')],
  'F58FFD': ['а) нет; б) нет; в) 3', text('Пусть в первой школе n учеников, во второй m=51−n.', 'а) Удвоение среднего после удаления потребовало бы переводимого балла A(2−n), который не положителен.', 'б) При росте на 10% переводимый балл равен B(62−n):10. Для B=1 целочисленность возможна только при n=2, но тогда условие первой школы не выполняется.', 'в) При n=2, A=20, B=3, x=18 обе новые средние возрастают на 10%. Для n=2,…,10 минимальные B равны 3,40,35,10,5,4,5,10,5. Ответ: 3.')],
  'F89087': ['а) нет; б) нет; в) 9', text('Как и в задаче 354582, все числа имеют один остаток по модулю 60. Так как 30033≡33, все числа имеют остаток 33.', 'а) 303≡3, поэтому нет. б) Равенство y=31x потребовало бы делимости 30x на 60, то есть чётности x; число с остатком 33 нечётно.', 'в) Для y=n²x нужно 20 делит n²−1. Наименьшее n>1 равно 9; пример: 33 и 2673. Ответ: 9.')],
  'FB6A82': ['а) да; б) нет; в) ⟦232¦21⟧', text('Пусть суммы групп A,B,C, числа элементов a,b,c. Новая сумма равна 10A+3a+10B+7b+C.', 'а) Для групп {1},{8},{4} получаем 104=8·13. б) Увеличение в 17 раз невозможно, поскольку все три группы непусты и равенство требовало бы предельного множителя 17 только для числа 1 во второй группе.', 'в) Докажем верхнюю оценку. Неравенство 22A+22B+211C≥63a+147b следует из различности натуральных чисел: худший случай даёт C=1, A={2}, B={3,4,5,6}. Поэтому отношение новой суммы к старой не больше 10+⟦22¦21⟧=⟦232¦21⟧. В указанном случае новая сумма 232, старая 21, так что оценка достигается.')],
  '0BA332': ['32 000', text('Долги в июле равны S, ⟦3S¦4⟧, ⟦9S¦16⟧, ⟦27S¦64⟧, 0. Сумма платежей равна S+⟦1¦4⟧(S+⟦3S¦4⟧+⟦9S¦16⟧+⟦27S¦64⟧)=⟦431S¦256⟧.', 'Из ⟦431S¦256⟧=53875 получаем S=32000. Ответ: 32 000.')],
  '2A731E': ['30', text('Долг ежемесячно уменьшается на ⟦A¦24⟧. В 2028 году погашается ⟦A¦2⟧ основного долга, а сумма долгов перед начислением процентов равна 3,25A.', 'Поэтому 0,5A+0,03·3,25A=17,925; 0,5975A=17,925, A=30. Ответ: 30.')],
  '31E106': ['5%', text('Долги в июле: 12, 10,8, 9,72, 0 млн. Сумма всех платежей равна 12+⟦r¦100⟧(12+10,8+9,72)=13,626.', 'Отсюда 0,271r=1,355, r=5. Ответ: 5%.')],
  '3EFF42': ['10 755', text('Ежемесячное уменьшение долга равно 27:36=0,75 млн. В 2029 году погашается 9 млн, а сумма долгов перед процентами равна 27·⟦12+…+1¦36⟧=58,5 млн.', 'Платежи за 2029 год: 9+0,03·58,5=10,755 млн рублей. Ответ: 10 755.')],
  '423D7F': ['2%', text('За 2027 год погашается 3 млн. Сумма двенадцати долгов перед начислением процентов равна 91,5 млн.', '3+91,5·⟦r¦100⟧=4,83, поэтому r=2. Ответ: 2%.')],
  '45786C': ['6', text('За первый год погашается ⟦A¦5⟧, а сумма долгов перед процентами равна 10,9A. Поэтому 0,2A+0,02·10,9A=2,508.', '0,418A=2,508, откуда A=6 млн рублей. Ответ: 6.')],
  '593156': ['9 000', text('Долги в июле равны S,0,3S,0,09S,0. Сумма платежей равна S+0,2(S+0,3S+0,09S)=1,278S.', '1,278S=11502, S=9000. Ответ: 9 000.')],
  '5D3B2F': ['3 595', text('Долги в июле: 2500,1750,1225,0. Сумма платежей равна 2500+0,2(2500+1750+1225)=3595. Ответ: 3 595.')],
  '6066EB': ['182 000', text('Пусть равный ежегодный платёж A. При коэффициенте 1,2 сумма кредита равна A(⟦1¦1,2⟧+⟦1¦1,2²⟧+⟦1¦1,2³⟧). Переплата равна 77200.', 'Из 3A−S=77200 получаем A=86400, S=182000. Ответ: 182 000.')],
  '62784B': ['30 000', text('Долги в июле: S,0,8S,0,64S,0,512S,0. Общая выплата равна S+0,2·2,952S=1,5904S.', '1,5904S=47712, S=30000. Ответ: 30 000.')],
  '6D2E6D': ['201 300', text('Равный платёж равен 311040:4=77760. Первоначальный долг равен 77760(⟦1¦1,2⟧+⟦1¦1,2²⟧+⟦1¦1,2³⟧+⟦1¦1,2⁴⟧)=201300. Ответ: 201 300.')],
  '78CB01': ['1%', text('В 2030 году погашается 3 млн основного долга. Сумма долгов перед процентами за эти двенадцать месяцев равна 19,5 млн.', '3+19,5·⟦r¦100⟧=3,195, откуда r=1. Ответ: 1%.')],
  '81455C': ['4 995', text('За 2027 год погашается 3 млн. Сумма двенадцати долгов перед начислением процентов равна 199,5 млн.', 'Сумма платежей равна 3+0,01·199,5=4,995 млн рублей. Ответ: 4 995.')],
  '8F933F': ['20%', text('Долги в июле: 40,30,22,5,16,875,0. Их сумма равна 109,375 млн.', '40+⟦r¦100⟧·109,375=61,875. Получаем r=20. Ответ: 20%.')],
  'A3CDCA': ['1 830', text('Первые три платежа равны 126 тыс. Пусть два последних равны X. Долг после предпоследнего платежа равен 1,1·1260−X, а последний платёж равен 1,1 этого долга.', 'Из X=1,1(1386−X) получаем X=726. Сумма 3·126+2·726=1830 тыс. Ответ: 1 830.')],
  'B1B74D': ['25%', text('Долги в июле: 6,1,8,0,54,0. Сумма выплат равна 6+⟦r¦100⟧·8,34=8,085.', '0,0834r=2,085, r=25. Ответ: 25%.')],
  'B9281F': ['20%', text('Первые три платежа равны 6,6·⟦r¦100⟧. Пусть q=1+⟦r¦100⟧. Равенство последних двух платежей даёт каждый из них ⟦q²·6,6¦q+1⟧.', 'Из 3(q−1)+⟦2q²¦q+1⟧=12,6:6,6=⟦21¦11⟧ получаем 55q²−21q−54=0, q=1,2. Ответ: 20%.')],
  'D15112': ['11%', text('Основной долг каждый месяц уменьшается на 20% кредита. Переплата равна ⟦r¦100⟧(1+0,8+0,6+0,4) кредита=2,8⟦r¦100⟧ кредита.', 'Нужно 2,8⟦r¦100⟧>0,3, то есть r>⟦75¦7⟧. Наименьшее целое r равно 11. Ответ: 11%.')],
  'D334F2': ['300 000', text('При четырёх равных платежах с коэффициентом 1,25 первоначальный долг равен A(0,8+0,64+0,512+0,4096)=2,3616A.', '177120=2,3616A, A=75000. Общая сумма 4A=300000. Ответ: 300 000.')],
  '135C80': ['18√30', text('а) В координатах основания A(−6;−6;0), B(6;−6;0), C(6;6;0), D(−6;6;0), S(0;0;h) имеем M(0;−6;0), K(−3;3;⟦h¦2⟧). Вектор MK равен ⟦1¦2⟧BS+⟦1¦2⟧BC, поэтому он параллелен плоскости SBC. Точка M ей не принадлежит, следовательно, прямая MK параллельна этой плоскости.', 'б) Проекция MK на основание имеет длину 3√10, а вертикальная составляющая равна ⟦h¦2⟧. Поэтому tan60°=⟦h¦2·3√10⟧, откуда h=18√30. Ответ: 18√30.'), geometryDiagram('Пирамида SABCD, M — середина AB, K — середина SD')],
  '33A81C': ['⟦√21¦7⟧', text('а) Так как AB∥CD, плоскость α параллельна CD, следовательно MN∥CD. Треугольники SNM и SDC подобны. Из MN=⟦AB¦5⟧=⟦CD¦5⟧ получаем SM:SC=SN:SD=1:5, то есть SM:MC=SN:ND=1:4.', 'б) Пусть MN=x. Тогда AB=AN=BM=5x. Высота равнобедренной трапеции ABMN равна √21x, её площадь 3√21x². Ортогональная проекция трапеции на основание имеет площадь 9x². Поэтому косинус угла между плоскостями равен 9x²:(3√21x²)=√21:7. Ответ: ⟦√21¦7⟧.'), geometryDiagram('Сечение ABMN правильной четырёхугольной пирамиды')],
  '5C14CA': ['8:1', text('а) Проекция ребра SC на основание — OC. Диагональ BD проходит через O и перпендикулярна OC, значит, по теореме о трёх перпендикулярах BD⊥SC. Поэтому единственная плоскость через O, перпендикулярная SC, содержит B и D.', 'б) Пусть h — высота пирамиды, а P=α∩SC. В треугольнике BPD основание BD=√2, а высота PO. Из перпендикулярности получаем S(BPD)²=⟦h²¦2(2h²+1)⟧. По условию это 2:9, откуда h²=4. Тогда SP:PC=2h²:1=8:1. Ответ: 8:1.'), geometryDiagram('Сечение BPD через диагональ BD')],
  '69A4ED': ['⟦√6¦3⟧', text('а) AM:MB=AK:KD=2:1, поэтому MK∥BD, а треугольники AMK и ABD подобны с коэффициентом 2:3. Их площади относятся как 4:9. Две части тетраэдра имеют общую высоту из C, поэтому объёмы относятся как площади трапеции BMKD и треугольника AMK, то есть 5:4.', 'б) Пусть T — середина BD, L=AT∩MK. Плоскость ACT перпендикулярна MK, поэтому искомый угол равен углу ACL. AT=CT=3√3, AL=2√3. По теореме косинусов CL=2√6, затем cos∠ACL=(36+24−12):(2·6·2√6)=√6:3. Ответ: ⟦√6¦3⟧.'), geometryDiagram('Тетраэдр ABCD, сечение CMK')],
  'CE2EC7': ['2√6', text('а) Положим высоту и сторону основания равными a. В координатах A(0;0;0), B(a;0;0), C(⟦a¦2⟧;⟦a√3¦2⟧;0), M(0;0;⟦2a¦3⟧) плоскость α, перпендикулярная грани ABB₁A₁, имеет уравнение z=⟦2a¦3⟧+⟦2x¦3⟧. На ребре A₁B₁, где z=a, получаем x=⟦a¦2⟧, то есть середину.', 'б) Сечение — треугольник MNC₁. Его площадь по векторному произведению равна ⟦a²√39¦24⟧. По условию она равна √39, поэтому a²=24, a=2√6. Ответ: 2√6.'), geometryDiagram('Призма ABCA₁B₁C₁, сечение MNC₁')],
  'EFF32E': ['1:2', text('Пусть α пересекает AB и AD в M и N. Ортогональная проекция K на основание лежит на AC. В равностороннем сечении KMN точка проекции является серединой MN, поэтому MN∥BD и MN⊥AC. Поскольку α перпендикулярна основанию и содержит MN, получаем α⊥AC.', 'Пусть сторона основания a, высота h, а SK:KA=t:(1−t). Из равносторонности сечения h²=⟦3a²¦2⟧. Объём a²h:3=18√3 даёт a=3√2, h=3√3. Сторона сечения MN=√2a(1−t)=6(1−t). Из площади 4√3 получаем MN=4, значит 1−t=⟦2¦3⟧ и t=⟦1¦3⟧. Ответ: 1:2.'), geometryDiagram('Вертикальное равностороннее сечение KMN')]
};

Object.assign(updates, {
  'F37F75': ['а) да; б) нет; в) 27', text('Пусть B — число синих карточек, а R — число красных. Максимальное красное число равно 2B и должно быть чётным, а максимальное синее число равно R и должно делиться на 3. Числа на карточках строго больше −36.', 'Синие числа — различные кратные 3 от −33 до R, поэтому их число не превосходит ⟦R¦3⟧+12. Красные числа — различные чётные числа от −34 до 2B, поэтому их число не превосходит B+18. Так как карточек ровно B и R, получаем B≤⟦R¦3⟧+12 и R≤B+18. Первое неравенство даёт R≥3B−36, а вместе со вторым — 3B−36≤B+18, то есть B≤27.', 'а) При B=1 и R=3 можно выбрать допустимые наборы карточек, значит, одна синяя карточка возможна. б) B=50 противоречит доказанной оценке B≤27. в) При B=27 и R=45 обе оценки достигаются: синие кратные 3 от −33 до 45, красные чётные от −34 до 54. Поэтому максимум равен 27. Ответ: а) да; б) нет; в) 27.')],
  '6FF25E': ['а) да; б) нет; в) 75', text('Обозначим через B число синих карточек, а через R число красных. Максимальное красное число равно 2B и является чётным; максимальное синее число равно R и делится на 3. Все числа больше −60.', 'Синих различных кратных 3 от −57 до R не более ⟦R¦3⟧+20, поэтому B≤⟦R¦3⟧+20. Красных различных чётных чисел от −58 до 2B не более B+30, поэтому R≤B+30. Из первого неравенства R≥3B−60, следовательно, 3B−60≤B+30 и B≤45. Тогда R≤75.', 'а) При R=3 можно взять B=1 и подобрать карточки с нужными максимальными числами. б) При R=150 второе неравенство требует B≥120, тогда как первое даёт B≤70, что невозможно. в) B=45 и R=75 достигают обеих границ: синие числа идут от −57 до 75 с шагом 3, красные — от −58 до 90 с шагом 2. Ответ: а) да; б) нет; в) 75.')],
  'A87FAB': ['а) да; б) нет; в) 30', text('Пусть B — количество синих карточек, R — количество красных. Максимальное красное число равно 3B и делится на 3, максимальное синее число равно R и делится на 5. Все числа больше −45.', 'Синие числа — различные кратные 5 от −40 до R, их не более ⟦R¦5⟧+9. Красные числа — различные кратные 3 от −42 до 3B, их не более B+15. Поэтому B≤⟦R¦5⟧+9 и R≤B+15. Из первого получаем R≥5B−45; вместе со вторым это даёт 5B−45≤B+15, то есть B≤15 и R≤30.', 'а) При B=1 и R=5 условия выполнимы. б) R=100 потребовало бы B≥85 из второго неравенства, но первое ограничивает B значением 29, поэтому это невозможно. в) B=15 и R=30 достигают обеих границ, так что максимум равен 30. Ответ: а) да; б) нет; в) 30.')],
  'E8AA65': ['а) да; б) нет; в) 150', text('Пусть B — количество синих карточек, R — количество красных. Максимальное красное число равно 2B, максимальное синее число равно R и делится на 5. Все числа больше −120.', 'Синие числа — различные кратные 5 от −115 до R, поэтому B≤⟦R¦5⟧+24. Красные числа — различные чётные от −118 до 2B, поэтому R≤B+60. Из первого следует R≥5B−120; вместе со вторым получаем 5B−120≤B+60, то есть B≤45 и затем R≤105. Значит, общее количество карточек не превосходит 150.', 'а) При B=1 и R=5 можно выбрать ровно шесть карточек, поэтому это возможно. б) Условие R=B+90 противоречит оценке R≤B+60. в) При B=45 и R=105 оба предела достигаются наборами всех подходящих чисел от нижней границы до максимума. Ответ: а) да; б) нет; в) 150.')]
});

// Дополнительные пояснения к ранее опубликованным решениям раздела «Числа».
// Они намеренно отделены от исходных заготовок: так публикацию можно повторить
// одной командой и не потерять расширенные обоснования.
const detailedAdditions = {
  '7C3FDA': text('Пояснение к оценке: если числа упорядочены, то сумма первых шести равна 30, а сумма последних шести — 90. Поэтому общая сумма равна 120−(x₅+x₆). Из неравенств x₁<…<x₆ и натуральности следует x₅≥5 и x₆≥6; проверка возможных значений средней пары показывает, что наибольшая общая сумма достигается при x₅+x₆=20. Набор 1,2,3,4,5,15,16,17,18,19 подтверждает достижимость.', 'Таким образом, три ответа следуют не из примера, а из необходимых ограничений на упорядоченные числа; каждый приведённый набор дополнительно проверяет обе заданные суммы.'),
  '7CA5F3': text('Каждый ход переносит одинаковое число камней из одной коробки в другую, поэтому общая сумма сохраняется. Кроме того, разность содержимого первой и третьей коробок меняется на число, кратное 3; это даёт инвариант по модулю 3.', 'Для верхней оценки в пункте в зафиксируем одно каменное содержимое первой коробки. Остальные два содержимых должны иметь определённые остатки по модулю 3, а их минимальные неотрицательные представители задают верхнюю границу для третьей коробки. Приведённая последовательность ходов достигает этой границы, поэтому оценка точна.'),
  '8381FC': text('При переносе трёх камней сумма сохраняется, а разности между коробками меняются на величины, кратные 4. Поэтому остатки четырёх содержимых по модулю 4 сохраняются относительно друг друга. Начальная конфигурация задаёт остатки 0,1,2,3 в фиксированном порядке.', 'Если в первой коробке X камней, то минимально допустимые содержимые остальных коробок имеют остатки X−3, X−2 и X−1 по модулю 4. Их сумма вместе с X не может превысить 306, откуда X≤303. Конструкция (303;0;1;2) имеет нужные остатки и достигается указанными переносами.'),
  '8755EE': text('После одного разреза один кусок превращается максимум в два, то есть число кусков не более чем удваивается на каждом шаге. Поэтому после семи ходов из одного куска получится не более 128 кусков, и семи ходов для 100 кусков недостаточно.', 'Восемь ходов достаточны: после трёх ходов получаем восемь кусков по 25, а каждый из них за пять следующих ходов можно разложить в 25 единичных кусков, последовательно используя разбиения 25 на 12 и 13, затем на 6,6,6,7 и далее. Значит, нижняя оценка и конструкция совпадают.'),
  '920C72': text('Обозначим первое число через 10q+d, где последняя цифра d принимает значения от 1 до 6. Четыре последовательных числа имеют общий множитель 10q, поэтому после вынесения q сумма выражается одной формулой через d. Это позволяет проверить шесть возможных значений d без перебора всех чисел.', 'Для d=1 целочисленность суммы требует, чтобы q делилось на 6. Максимальное q, при котором первое число остаётся трёхзначным, равно 96; подстановка даёт 2004. При d≥2 получаем меньшие значения, поэтому найденное число действительно наибольшее.'),
  '9C9614': text('Минимальная сумма 100 различных натуральных чисел равна 1+2+…+100=5050. Если обязательно присутствует 230, минимальная сумма получается заменой 100 на 230 и равна 5180, что уже больше 5120. Если исключить 14, в минимальном наборе 1,…,101 нужно заменить 14 следующим допустимым числом, и сумма становится 5137.', 'Для пункта в подсчитаем минимальную сумму при наличии не более трёх кратных 14. Она равна 5152 и превышает 5120, значит, нужно не менее четырёх. Набор с 14,28,42,56 и 96 подходящими числами после замены 103 на 119 даёт ровно 5120, поэтому нижняя оценка достигается.'),
  'A68DFB': text('Если заменить в выбранной четвёрке или пятёрке одно число другим, разность двух целых средних показывает, что разность любых двух чисел делится одновременно на 4 и на 5. Значит, все числа сравнимы по модулю 20. Число 403 задаёт остаток 3.', 'Остаток 2013 по модулю 20 равен 13, поэтому пункт а невозможен. Квадрат числа с остатком 3 имеет остаток 9, а не 3, что даёт пункт б. Для пункта в требуется n²≡1 по модулю 20; значения 2,3,4,5 не подходят, а 9²−1 делится на 20. Числа 1 и 81 показывают достижимость.'),
  'A8EFB6': text('Пусть k чисел оканчиваются на 7. Все остальные числа чётны, поэтому сумма последних цифр показывает, что k должно быть чётным. Для проверки минимальных сумм берём наименьшие возможные различные числа каждого типа.', 'При двух числах с последней цифрой 7 минимальная сумма уже превышает 810, а при четырёх можно подобрать 2,4,…,50,72 и 7,17,27,37. Их сумма равна 810, поэтому четыре — точная нижняя граница.'),
  'AB0F0C': text('Упорядочим четыре числа x₁<x₂<x₃<x₄. Ограничения на произведения дают x₁x₂>60 и x₃x₄<140. Для пяти и шести чисел сравниваем произведения крайних пар и получаем невозможность шести, а пример пяти даёт существование.', 'Для минимальной суммы четырёх чисел сначала перебираем допустимое x₁. При x₁=1 второе число должно быть больше 60, что сразу увеличивает сумму; при x₁≥4 нижняя граница достигается набором, указанным в основном решении. Проверка всех соседних целых значений показывает, что меньшая сумма нарушает одно из двух произведений.'),
  'AB3CF8': text('Рассмотрим остатки чисел по модулю 4. Сравнение соседних сумм четырёх чисел показывает, что остатки повторяются с периодом 4. Условие на сумму трёх соседних чисел исключает периоды с одинаковыми остатками и оставляет две единицы и две двойки в каждом периоде.', 'При N, кратном 4, в каждом периоде можно иметь не более четырёх чисел, а ограничение различности и верхняя граница 365 дают N≤184. Для проверки точности выписываем допустимый период и повторяем его до нужной длины; остатки всех трёх- и четырёхчленных сумм затем проверяются непосредственно.'),
  'AED2BB': text('Обозначим числа через x₁<…<x₁₁. Из условий на средние шести чисел получаем x₁+…+x₆=30 и x₆+…+x₁₁=90. Поэтому выражение S−B можно переписать через сумму всех чисел и шестое число, после чего задача сводится к оценке четырёх крайних чисел.', 'Минимальные значения первых чисел и строгий порядок задают нижнюю границу, а сумма последних чисел — верхнюю. Подстановка набора 1,2,3,4,5,15,16,17,18,19,20 показывает, что полученная оценка достигается; ответ записан в основном решении.'),
  'B5D110': text('Если исходные суммы трёх групп обозначить A,B,C, а количества чисел — a,b,c, то приписывание цифр 1 и 8 увеличивает сумму на 10A+3a+10B+7b+C. Это выражение сравниваем с исходной суммой A+B+C.', 'При увеличении в 11 раз переносим исходную сумму в одну часть равенства и получаем линейное ограничение на A,B,C и количества элементов. Минимальные различные натуральные числа в каждой группе дают верхнюю границу числа элементов; указанная в основном решении конфигурация достигает её.'),
  'C690EB': text('Количество записанных чисел строго уменьшается, а дневная сумма строго возрастает. Поскольку каждое число не превосходит 5, для каждого следующего дня сумма ограничена произведением 5 на его количество. Сопоставление этих двух последовательностей сразу ограничивает число дней.', 'Для максимума фиксируем число элементов каждого дня и заполняем последний день пятёрками, затем предыдущие дни — наибольшими допустимыми числами при сохранении строгого роста сумм. Получается последовательность, приведённая в основном решении; любая попытка увеличить одну из сумм нарушает ограничение на количество элементов.'),
  'C794EA': text('Из 599=1+2+…+34+4 следует естественная проверка представимости сумм различными натуральными числами. Для нижней границы рассматриваем остаток требуемого числа после выбора наименьших слагаемых.', 'Если сумма имеет вид 2043, то после выделения максимального допустимого набора остаётся остаток, который нельзя получить меньшим числом слагаемых. Конструкция из 231 слагаемого перечисляется в основном решении; её сумма проверяется обычным сложением, поэтому оценка достигается.'),
  'CFEFEF': text('Каждая цифра набора используется ровно один раз в каждом из двух чисел, поэтому сумма соответствующих произведений не превосходит суммы пяти произведений 9·9. Для максимума в пункте в достаточно рассмотреть дефицит от этой верхней границы.', 'Минимальные дефициты при уменьшении произведения с 81 дают последовательность, из которой видно, какие значения недостижимы. Для 10035 приведён пример пяти чисел; вычисление произведений их соответствующих цифр даёт ровно требуемую сумму.'),
  'D51CAD': text('Пусть rᵢ — остатки чисел по модулю 3. Из делимости каждой суммы четырёх соседних чисел следует rᵢ₊₄=rᵢ. Условие на тройки запрещает нулевую сумму в любом окне, поэтому в периоде остаются две единицы и две двойки.', 'В каждом полном периоде из четырёх позиций можно разместить только четыре числа. При N=360 потребовалось бы равное количество остатков, но условие на тройки нарушается; при N=149 остатки также не удаётся продолжить. Периодическая конструкция для 266 позиций показывает достижимость верхней оценки.'),
  'D5588E': text('Пусть x₁<…<x₁₀. Условия дают x₁+…+x₆=36 и x₅+…+x₁₀=72, поэтому сумма всех чисел равна 108−(x₅+x₆). Для проверки каждого пункта достаточно оценить среднюю пару с учётом строгого порядка.', 'Если x₁₀=14, первые шесть чисел не могут иметь сумму 36 при требуемом порядке и последних числах. Среднее 8,4 означало бы x₅+x₆=24, но тогда четыре наибольших числа уже превышают допустимую сумму. Набор из основного решения даёт x₅+x₆=19 и среднее 8,9.'),
  'D6152F': text('Пусть во второй школе m учеников со средним 42, а переведённый ученик набрал x. После перехода средний стал 37,8, поэтому уравнение ⟦42m−x¦m−1⟧=37,8 выражает x через m. Требование натуральности оставляет конечный набор значений m.', 'Для пункта б сумма баллов второй школы равна 42m, а каждый из m учеников набрал больше x. Вычитая минимально возможные баллы остальных учеников, получаем верхнюю границу для одного результата. В пункте в аналогичное уравнение для первой школы даёт A(n+9)=210; перебор делителей 210 подтверждает максимум n=96.'),
  'E5791E': text('Для упорядоченной тройки a<b<c условие удачности равносильно a≥⟦b+c¦3⟧+5: именно наименьшее число даёт наиболее сильное ограничение. Это позволяет отдельно решить каждый пункт без перебора всех троек.', 'При 50 и 60 получаем c≤75, поэтому считаем целые c от 61 до 75. Для числа 15 проверка соседней тройки 15,16,17 даёт нарушение, а при перестановке условие только усиливается. В конструкции на 80 числах каждая тройка проверяется по разности не более четырёх.'),
  'E983D6': text('Пусть в первой школе n учеников, во второй 9−n, а переводимый результат равен x. После перехода суммы и количества учеников меняются на x и на единицу, поэтому оба условия о десятипроцентном изменении превращаются в линейные уравнения.', 'Для каждого n от 2 до 7 проверяем целочисленность среднего и натуральность x. Получаются минимальные возможные значения второго среднего 55,20,65,14,5,80; наименьшее 5 достигается при n=6 и переводимом результате 3.'),
  'EA76EF': text('Упорядочим числа. Ограничение произведения двух наименьших даёт нижнюю границу, а произведение двух наибольших — верхнюю. Набор 5,6,7,8,9 удовлетворяет обеим границам, поэтому пять чисел возможны.', 'Для шести чисел последние два при любом допустимом начале имеют произведение не меньше 9·10=90, что противоречит строгому ограничению 85. Для четырёх чисел максимальная сумма получается при наборе 7,8,9,11; его крайние произведения 56 и 99 не нарушают условий, а увеличение любого элемента нарушает верхнюю границу.'),
  'EC9829': text('Пусть числа упорядочены. Для пяти чисел набор 6,7,8,9,10 проверяется по крайним произведениям: 6·7>40 и 9·10<100. Для шести чисел первые два варианта начала приводят к последним двум числам не меньше 10 и 11, поэтому произведение превышает 100.', 'Для максимальной суммы четырёх чисел минимально допустимый третий элемент равен 9, а четвёртый тогда не превосходит 11. Набор 7,8,9,11 даёт сумму 35; при меньшем третьем элементе верхняя граница четвёртого уменьшается, так что больше получить нельзя.'),
  'F58FFD': text('Обозначим средние и количества учеников в двух школах через A,n и B,m, причём n+m=51. После перехода одного ученика изменения средних на 10 процентов дают два линейных уравнения для его результата.', 'В пункте а результат, необходимый для удвоения среднего первой школы, был бы неположительным. В пункте б при B=1 требование целочисленности возможно только при n=2, но тогда условие первой школы нарушается. Для пункта в перебираем n от 2 до 10 и выбираем минимальное целое B; минимум равен 3 и достигается при n=2.'),
  'F89087': text('Из целочисленности средних любых трёх, четырёх, пяти и шести чисел следует, что разность любых двух записанных чисел делится на 3,4,5 и 6. Поэтому все числа сравнимы с 30033 по модулю 60, то есть имеют остаток 33.', 'Число 303 имеет остаток 3, поэтому пункт а невозможен. Если отношение двух чисел равно 31, то разность равна 30x и должна делиться на 60; это требует чётности x, противоречащей остатку 33. Для квадратного отношения требуется 20 делит n²−1; минимальное n>1 — 9, и пример 33 и 2673 подтверждает достижимость.'),
  'FB6A82': text('После приписывания цифр 3 и 7 суммы трёх групп A,B,C превращаются в 10A+3a+10B+7b+C. Разделив новое выражение на исходную сумму A+B+C, получаем отношение, которое нужно оценить при непустых группах.', 'Для пункта а группы {1},{8},{4} дают исходную сумму 13 и новую сумму 104, то есть множитель 8. Множитель 17 невозможен: для него пришлось бы одновременно получить предельный вклад от цифры 7 и оставить положительную третью группу. В пункте в минимальные различные числа в группах дают верхнюю оценку ⟦232¦21⟧; конфигурация из основного решения достигает её.')
};

const db = new DatabaseSync(path.join(__dirname, '..', 'storage', 'solutions.sqlite'));
const save = db.prepare(`INSERT INTO solutions (task_id, answer, solution, diagram_svg, diagram_caption, published, created_at, updated_at)
VALUES (?, ?, ?, ?, ?, 1, ?, ?)
ON CONFLICT(task_id) DO UPDATE SET answer=excluded.answer, solution=excluded.solution, diagram_svg=excluded.diagram_svg, diagram_caption=excluded.diagram_caption, published=1, updated_at=excluded.updated_at`);
const now = new Date().toISOString();
db.exec('BEGIN');
try {
  for (const [taskId, [answer, rawSolution, diagram = '']] of Object.entries(updates)) {
    const expandedSolution = detailedAdditions[taskId] ? text(rawSolution, detailedAdditions[taskId]) : rawSolution;
    const solution = expandedSolution.includes('Ответ:') ? expandedSolution : `${expandedSolution}\n\nОтвет: ${answer}.`;
    if (!answer || answer.includes('/') || solution.includes('/')) throw new Error(`Некорректное решение ${taskId}`);
    save.run(taskId, answer, solution, diagram, diagram ? 'Схема к стереометрическому решению.' : '', now, now);
  }
  db.exec('COMMIT');
} catch (error) {
  db.exec('ROLLBACK');
  throw error;
}
console.log(`Опубликовано решений: ${Object.keys(updates).length}`);
